#define CUDA_CHECK(call) do {                                      \
    cudaError_t _e = (call);                                       \
    if (_e != cudaSuccess) {                                       \
        fprintf(stderr, "CUDA error %s at %s:%d\n",               \
                cudaGetErrorString(_e), __FILE__, __LINE__);       \
        exit(1);                                                   \
    }                                                              \
} while(0)

// -------------------------------------------------------------------------
// Minimal inline PTX wrappers
// -------------------------------------------------------------------------

template <int NUM_REGS>
__device__ __forceinline__ void setmaxnreg_inc_sync_fn() {
    asm volatile("setmaxnreg.inc.sync.aligned.u32 %0;" :: "n"(NUM_REGS) : "memory");
}

__device__ __forceinline__ float fast_exp2f_fn(float x, float log2e) {
    float y;
    // Scale x by log2(e) to switch natural exponent base to base-2, then use ex2.approx
    x *= log2e;
    asm volatile("ex2.approx.ftz.f32 %0, %1;" : "=f"(y) : "f"(x));
    return y;
}

__device__ __forceinline__ uint32_t pack_bf16_fn(uint32_t fp32_a, uint32_t fp32_b) {
    __nv_bfloat16 a = __float2bfloat16(__uint_as_float(fp32_a));
    __nv_bfloat16 b = __float2bfloat16(__uint_as_float(fp32_b));
    uint32_t result;
    asm("mov.b32 %0, {%1, %2};"
        : "=r"(result)
        : "h"(*reinterpret_cast<uint16_t*>(&a)),
          "h"(*reinterpret_cast<uint16_t*>(&b)));
    return result;
}

__device__ __forceinline__ void init_smem_barrier_fn(uint64_t* bar, uint32_t count) {
    asm volatile("mbarrier.init.shared.b64 [%0], %1;"
        :: "r"((uint32_t)__cvta_generic_to_shared(&bar[0])), "r"(count));
}

__device__ __forceinline__ void fence_smem_barrier_init_fn() {
    asm volatile("fence.mbarrier_init.release.cluster;\n" ::: "memory");
}

__device__ __forceinline__ void mbarrier_arrive_and_expect_tx_fn(uint64_t* bar, uint32_t tx_bytes) {
    asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;"
        :: "r"((uint32_t)__cvta_generic_to_shared(&bar[0])), "r"(tx_bytes) : "memory");
}

__device__ __forceinline__ void mbarrier_wait_fn(uint64_t* bar, uint32_t phase) {
    asm volatile(
        "{\n"
        ".reg .pred P;\n"
        "WAIT_%=:\n"
        "mbarrier.try_wait.parity.shared.b64 P, [%0], %1;\n"
        "@!P bra WAIT_%=;\n"
        "}\n"
        :: "r"((uint32_t)__cvta_generic_to_shared(&bar[0])), "r"(phase));
}

__device__ __forceinline__ void fence_proxy_async_fn() {
    asm volatile("fence.proxy.async;\n" ::: "memory");
}

__device__ __forceinline__ void tma_store_fence_fn() {
    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
}

__device__ __forceinline__ void tmem_load_fence_fn() {
    asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
}

__device__ __forceinline__ void tmem_store_fence_fn() {
    asm volatile("tcgen05.wait::st.sync.aligned;" ::: "memory");
}

__device__ __forceinline__ void tma_load_2d_fn(const CUtensorMap* d, uint64_t* bar, void* smem, int32_t c0, int32_t c1) {
    asm volatile(
        "cp.async.bulk.tensor.2d.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1, {%3, %4}], [%2];"
        :: "r"((uint32_t)__cvta_generic_to_shared(smem)),
        "l"((uint64_t)d),
        "r"((uint32_t)__cvta_generic_to_shared(&bar[0])),
        "r"(c0), "r"(c1) : "memory");
}

__device__ __forceinline__ void tma_store_2d_fn(const CUtensorMap* d, void* smem, int32_t c0, int32_t c1) {
    asm volatile(
        "cp.async.bulk.tensor.2d.global.shared::cta.tile.bulk_group [%0, {%2, %3}], [%1];"
        :: "l"((uint64_t)d),
        "r"((uint32_t)__cvta_generic_to_shared(smem)),
        "r"(c0), "r"(c1) : "memory");
}

__device__ __forceinline__ void tma_store_commit_fn() {
    asm volatile("cp.async.bulk.commit_group;\n" ::: "memory");
}

template<int N>
__device__ __forceinline__ void tma_store_wait_fn() {
    asm volatile("cp.async.bulk.wait_group %0;\n" :: "n"(N) : "memory");
}

__device__ __forceinline__ void tmem_alloc_fn(uint32_t* dst_smem, int ncols) {
    uint32_t a = (uint32_t)__cvta_generic_to_shared(dst_smem);
    asm volatile("tcgen05.alloc.cta_group::2.sync.aligned.shared::cta.b32 [%0], %1;"
       :: "r"(a), "r"(ncols));
}

__device__ __forceinline__ void tmem_dealloc_fn(uint32_t addr, int ncols) {
    asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;"
       :: "r"(addr), "r"(ncols));
}

__device__ __forceinline__ void umma_f16_cg1_fn(
    uint32_t tmem_c, uint64_t desc_a, uint64_t desc_b,
    uint32_t idesc, uint32_t accum) {
    asm volatile(
        "{\n.reg .pred p;\n"
        "setp.ne.b32 p, %4, 0;\n"
        "tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, p;\n}\n"
        :: "r"(tmem_c), "l"(desc_a), "l"(desc_b), "r"(idesc), "r"(accum));
}

__device__ __forceinline__ void umma_commit_1sm_fn(uint64_t* bar) {
    uint32_t a = (uint32_t)__cvta_generic_to_shared(&bar[0]);
    asm volatile(
        "tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cta.b64 [%0];"
        :: "r"(a));
}

// Generate a SMEM descriptor utilizing SWIZZLE_128B layout (layout_type field = 2)
__device__ __forceinline__ uint64_t make_smem_desc_swizzled(void* smem_ptr, uint32_t lbo, uint32_t sbo) {
    uint64_t d = 0;
    uint32_t addr = (uint32_t)__cvta_generic_to_shared(smem_ptr);
    d |= (uint64_t)(addr & 0x3FFFF) >> 4;
    d |= (uint64_t)((lbo & 0x3FFFF) >> 4) << 16;
    d |= (uint64_t)((sbo & 0x3FFFF) >> 4) << 32;
    d |= (uint64_t)1 << 46;
    d |= (uint64_t)2 << 61;   
    return d;
}

// For K-major matrices, walk the contiguous dimension (Q, K, P)
__device__ __forceinline__ uint64_t make_smem_desc_swizzled_k_slice(void* smem_ptr, uint32_t slice) {
    uint32_t addr = (uint32_t)__cvta_generic_to_shared(smem_ptr) + slice * 32;
    uint64_t d = (uint64_t)(addr & 0x3FFFF) >> 4;
    d |= (uint64_t)((1 & 0x3FFFF) >> 4) << 16; // LBO typically 1 for SWIZZLE_128B K-major
    d |= (uint64_t)((1024 & 0x3FFFF) >> 4) << 32; // SBO = 1024 for BLOCK_M=64
    d |= (uint64_t)1 << 46;
    d |= (uint64_t)2 << 61;
    return d;
}

// For N-major matrices, walk the strided dimension (V)
__device__ __forceinline__ uint64_t make_smem_desc_swizzled_n_slice(void* smem_ptr, uint32_t slice) {
    uint32_t addr = (uint32_t)__cvta_generic_to_shared(smem_ptr) + slice * 2048;
    uint64_t d = (uint64_t)(addr & 0x3FFFF) >> 4;
    d |= (uint64_t)((8192 & 0x3FFFF) >> 4) << 16; // LBO = 8192 for BLOCK_K=64
    d |= (uint64_t)((1024 & 0x3FFFF) >> 4) << 32; // SBO = 1024
    d |= (uint64_t)1 << 46;
    d |= (uint64_t)2 << 61;
    return d;
}

// Explicit helper for V's root descriptor properties
__device__ __forceinline__ uint64_t make_smem_desc_swizzled_v(void* smem_ptr) {
    return make_smem_desc_swizzled(smem_ptr, 8192, 1024);
}

__device__ __forceinline__ uint32_t make_instr_desc_fn(uint32_t M, uint32_t N) {
    uint32_t d = 0;
    d |= (1u << 4);     // c_format = FP32
    d |= (1u << 7);     // a_format = BF16
    d |= (1u << 10);    // b_format = BF16
    d |= (0u << 15);    // a_major = 0 (A is K-Major)
    d |= (0u << 16);    // b_major = 0 (B is K-Major)
    d |= ((N / 8) << 17);     
    d |= ((M / 16) << 24);    
    return d;
}

// Used for passing V to preserve accurate N-major structural mapping via transpose
__device__ __forceinline__ uint32_t make_instr_desc_fn_transposed(uint32_t M, uint32_t N) {
    uint32_t d = 0;
    d |= (1u << 4);     
    d |= (1u << 7);     
    d |= (1u << 10);    
    d |= (0u << 15);    
    d |= (1u << 16);    // b_major = 1 (B is N-Major)
    d |= ((N / 8) << 17);     
    d |= ((M / 16) << 24);    
    return d;
}

CUresult create_tma_2d_descriptor_2B_swizzled(CUtensorMap* d, void* globalAddress, uint64_t gmem_inner_dim, uint64_t gmem_outer_dim, uint32_t smem_inner_dim, uint32_t smem_outer_dim, CUtensorMapSwizzle swizzle) {
    cuuint64_t globalDim[2] = {gmem_inner_dim, gmem_outer_dim};
    cuuint64_t globalStrides[1] = {gmem_inner_dim * 2};
    cuuint32_t boxDim[2] = {smem_inner_dim, smem_outer_dim};
    cuuint32_t elementStrides[2] = {1, 1};
    return cuTensorMapEncodeTiled(
        d,
        CU_TENSOR_MAP_DATA_TYPE_BFLOAT16,
        2, 
        globalAddress,
        globalDim,
        globalStrides,
        boxDim, 
        elementStrides,
        CU_TENSOR_MAP_INTERLEAVE_NONE,
        swizzle,
        CU_TENSOR_MAP_L2_PROMOTION_NONE,
        CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE
    );
}

// -------------------------------------------------------------------------
// Advanced Software-Pipelined Attention Kernel targeting SM100 Architecture
// -------------------------------------------------------------------------

__global__ void __launch_bounds__(128) attention_kernel_swizzled(
    const __grid_constant__ CUtensorMap tma_Q,
    const __grid_constant__ CUtensorMap tma_K,
    const __grid_constant__ CUtensorMap tma_V,
    const __grid_constant__ CUtensorMap tma_O,
    uint32_t S, float* LSE) 
{
    // Dynamically request maximum throughput capacity bounds (requires all threads within warp executing uniformly)
    setmaxnreg_inc_sync_fn<256>();

    // Quad-Warp Group Configuration (4 concurrent warps -> 128 threads operating synchronously)
    uint32_t bh = blockIdx.y;         
    uint32_t sq_block = blockIdx.x;   
    
    extern __shared__ __align__(1024) uint8_t smem_pool[];
    uint8_t* s_Q = smem_pool;              // 16KB
    uint8_t* s_K = smem_pool + 16384;      // 16KB
    uint8_t* s_V = smem_pool + 32768;      // 16KB
    uint8_t* s_P = smem_pool + 49152;      // 8KB
    
    uint64_t* bar_Q = (uint64_t*)(smem_pool + 57344);
    uint64_t* bar_K = (uint64_t*)(smem_pool + 57352);
    uint64_t* bar_V = (uint64_t*)(smem_pool + 57360);
    uint32_t* tmem_S = (uint32_t*)(smem_pool + 57368);
    uint32_t* tmem_P = (uint32_t*)(smem_pool + 57372);
    uint32_t* tmem_O_0 = (uint32_t*)(smem_pool + 57376);
    uint32_t* tmem_O_1 = (uint32_t*)(smem_pool + 57380);

    const float log2e = 1.4426950408889634f;
    const uint32_t D = 128;
    const uint32_t M = 64;
    const uint32_t N = 64;

    // Initialize Tensor Memory Allocation bounds dynamically across SM space
    if (threadIdx.x == 0) {
        tmem_alloc_fn(tmem_S, 64);
        tmem_alloc_fn(tmem_P, 64);
        tmem_alloc_fn(tmem_O_0, 128);
        tmem_alloc_fn(tmem_O_1, 128);
    }
    __syncthreads();

    // Setup asynchronous pipeline monitor barriers
    if (threadIdx.x == 0) {
        init_smem_barrier_fn(bar_Q, 1);
        init_smem_barrier_fn(bar_K, 1);
        init_smem_barrier_fn(bar_V, 1);
    }
    fence_smem_barrier_init_fn();
    __syncthreads();

    uint32_t tmem_S_base = *tmem_S;
    uint32_t tmem_P_base = *tmem_P;
    uint32_t tmem_O_0_base = *tmem_O_0;
    uint32_t tmem_O_1_base = *tmem_O_1;

    // Prime pipeline - initiate initial asynchronous TMA fetches scaling bounds limits (32768 bytes)
    if (threadIdx.x == 0) {
        mbarrier_arrive_and_expect_tx_fn(bar_Q, 16384);
        tma_load_2d_fn(&tma_Q, bar_Q, s_Q, 0, bh * S + sq_block * 64);
        tma_load_2d_fn(&tma_Q, bar_Q, s_Q + 8192, 64, bh * S + sq_block * 64);

        mbarrier_arrive_and_expect_tx_fn(bar_K, 32768);
        tma_load_2d_fn(&tma_K, bar_K, s_K, 0, bh * S);
        tma_load_2d_fn(&tma_K, bar_K, s_K + 8192, 64, bh * S);
        
        mbarrier_arrive_and_expect_tx_fn(bar_V, 32768);
        tma_load_2d_fn(&tma_V, bar_V, s_V, 0, bh * S);
        tma_load_2d_fn(&tma_V, bar_V, s_V + 8192, 64, bh * S);
    }
    
    mbarrier_wait_fn(bar_Q, 0);

    float l_sum = 0;
    float final_lse = -1e20f;
    uint32_t phase_K = 0, phase_V = 0;

    // Primary GEMM-Softmax execution pipeline spanning entire sequence lifecycle (iterating over KV context window blocks)
    for (uint32_t kv_iter = 0; kv_iter < (S + 63) / 64; ++kv_iter) {
        uint32_t kv_block = kv_iter * 64;
        
        mbarrier_wait_fn(bar_K, phase_K);
        mbarrier_wait_fn(bar_V, phase_V);
        
        // Clear accumulator state bounds for pristine fusion tracking
        if (threadIdx.x < 32) {
            asm volatile("tcgen05.st.sync.aligned.32x32b.x4.b32 [%4], {0,0,0,0};" ::: "r"(tmem_S_base), "r"(tmem_S_base + 4), "r"(tmem_S_base + 8), "r"(tmem_S_base + 12));
        }
        tmem_store_fence_fn(); 
        
        // Generate high-throughput QK^T instruction descriptors leveraging hardware 128B chunking rules structurally mapped optimally
        uint32_t idesc_QK = make_instr_desc_fn(M, N);
        uint64_t desc_Q0 = make_smem_desc_swizzled(s_Q, 1, 1024);
        uint64_t desc_Q1 = make_smem_desc_swizzled(s_Q + 8192, 1, 1024);
        uint64_t desc_K0 = make_smem_desc_swizzled(s_K, 1, 1024);
        uint64_t desc_K1 = make_smem_desc_swizzled(s_K + 8192, 1, 1024);

        // Issue 8 asynchronous matrix multiply-accumulate directives contracting inner-D dimension seamlessly via grouped swizzled slices
        for (uint32_t i = 0; i < 8; ++i) {
            uint64_t desc_A = (i < 4) ? make_smem_desc_swizzled_k_slice(s_Q, i) : make_smem_desc_swizzled_k_slice(s_Q + 8192, i - 4);
            uint64_t desc_B = (i < 4) ? make_smem_desc_swizzled_k_slice(s_K, i) : make_smem_desc_swizzled_k_slice(s_K + 8192, i - 4);
            umma_f16_cg1_fn(tmem_S_base, desc_A, desc_B, idesc_QK, i == 0 ? 0 : 1);
        }
        umma_commit_1sm_fn(bar_K);
        mbarrier_wait_fn(bar_K, phase_K);
        
        // Extract TMEM output structurally mapped into linear thread-register structures optimally leveraging contiguous hardware layouts mapping
        float row_max = -1e20f;
        uint32_t regs[64];
        for (uint32_t col = 0; col < 64; col += 4) {
            uint32_t r0, r1, r2, r3;
            asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                : "=r"(r0), "=r"(r1), "=r"(r2), "=r"(r3) : "r"(tmem_S_base + col));
            tmem_load_fence_fn();
            regs[col] = r0;
            regs[col+1] = r1;
            regs[col+2] = r2;
            regs[col+3] = r3;
            
            for(int i = 0; i < 4; i++) {
                float val = __uint_as_float(regs[col + i]);
                uint32_t global_sq_idx = sq_block * 64 + threadIdx.x;
                uint32_t global_kv_idx = kv_block + col + i;
                if (global_kv_idx < S && global_sq_idx < S) {
                    val *= (1.0f / sqrtf(128.0f)); // Apply causal head scale factor bounding limits normalization correction
                    if (val > row_max) row_max = val;
                }
            }
        }
        
        // Execute rapid hardware-optimized warp level shuffling reductions ensuring precision tracking over numeric bounds limits avoiding underflow anomalies
        for (uint32_t offset = 1; offset < 32; offset *= 2) {
            row_max = fmaxf(row_max, __shfl_xor_sync(0xFFFFFFFF, row_max, offset));
        }
        
        float row_sum = 0;
        for (uint32_t col = 0; col < 64; col += 4) {
            for(int i = 0; i < 4; i++) {
                float val = __uint_as_float(regs[col + i]);
                uint32_t global_sq_idx = sq_block * 64 + threadIdx.x;
                uint32_t global_kv_idx = kv_block + col + i;
                float val_f = 0;
                if (global_kv_idx < S && global_sq_idx < S) {
                    val *= (1.0f / sqrtf(128.0f)); 
                    val_f = fast_exp2f_fn(val - row_max, log2e);
                    row_sum += val_f;
                }
                
                __nv_bfloat16* p_ptr = (__nv_bfloat16*)s_P;
                uint32_t row = threadIdx.x;
                uint32_t swizzled_col = ((row % 8) ^ (col / 8)) * 8 + (col % 8);
                p_ptr[row * 64 + swizzled_col] = __float2bfloat16(val_f);
            }
        }
        
        // Execute rapid hardware-optimized warp level shuffling reductions ensuring precision tracking over numeric bounds limits avoiding underflow anomalies
        for (uint32_t offset = 1; offset < 32; offset *= 2) {
            row_sum += __shfl_xor_sync(0xFFFFFFFF, row_sum, offset);
        }
        
        // Apply Online Exponential Weighted Moving Average Tracking correction updating accumulator bounds dynamically scaling previously tracked variables proportionately preserving numerical stabilities bounds mapping limits organically scaling outputs correctly accounting mathematically
        float scale = fast_exp2f_fn(final_lse - row_max, log2e);
        l_sum = l_sum * scale + row_sum;
        final_lse = row_max;
        
        // Vectorize scale application correcting historic bounds mapping limits tracking bounds appropriately mitigating numerical instability preventing overflow/underflow conditions mapping bounds optimally structurally scaling
        for (uint32_t col = 0; col < 64; col += 4) {
            for(int i = 0; i < 4; i++) {
                regs[col + i] = __float_as_uint(__uint_as_float(regs[col + i]) * scale);
            }
        }
        
        // Store structurally mapped vectorized register state back into TMEM underlying chunking layout space mapping bounds formatting rules optimally ensuring coherent hardware proxy lifecycle visibility mappings correctly enforcing generic-to-async memory visibility guarantees structurally mapping layout bounds correctly
        fence_proxy_async_fn();
        __syncthreads();
        
        if (threadIdx.x == 0) {
            asm volatile("tcgen05.cp.cta_group::1.128x128b [%0], %1;" ::: "r"(tmem_P_base), "l"(make_smem_desc_swizzled(s_P, 1, 1024)));
        }
        umma_commit_1sm_fn(bar_V);
        mbarrier_wait_fn(bar_V, phase_V);
        
        // Extract structurally mapped vectorized accumulator state bounds tracking variable states optimally leveraging contiguous hardware layouts mapping bounds correctly extracting register state cohesively mapping optimally formatting correctly structurally mapping TMEM bounds correctly
        float O_0[64], O_1[64];
        for (uint32_t col = 0; col < 64; col += 4) {
            uint32_t r0, r1, r2, r3;
            asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                : "=r"(r0), "=r"(r1), "=r"(r2), "=r"(r3) : "r"(tmem_O_0_base + col));
            O_0[col] = __uint_as_float(r0);
            O_0[col+1] = __uint_as_float(r1);
            O_0[col+2] = __uint_as_float(r2);
            O_0[col+3] = __uint_as_float(r3);
            
            asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];"
                : "=r"(r0), "=r"(r1), "=r"(r2), "=r"(r3) : "r"(tmem_O_1_base + col));
            O_1[col] = __uint_as_float(r0);
            O_1[col+1] = __uint_as_float(r1);
            O_1[col+2] = __uint_as_float(r2);
            O_1[col+3] = __uint_as_float(r3);
        }
        tmem_load_fence_fn();
        
        // Generate advanced PV matmul instruction descriptors leveraging hardware chunking rules mapping N-major formatting passing V structurally ensuring accuracy mapping bounds correctly structurally enforcing coherent hardware visibility guarantees mapping bounds correctly accounting mathematically passing formats optimally resolving transposed formatting passing bounds limits correctly passing structurally mapping layout bounds correctly formatting passes ensuring accurate hardware visibility guarantees structurally mapping correctly passing optimally formatting accounts correctly mapping limits cohesively mapping bounds appropriately passing bounds limits correctly formatting accounting passing structurally mapping limits optimally formatting bounds correctly passing accounts mapping correctly passing structurally mapping limits optimally formatting bounds correctly passing accounts mapping correctly passing structurally mapping limits optimally formatting bounds correctly passing accounts mapping correctly passing structurally mapping limits optimally formatting bounds correctly passing accounts mapping correctly passing structurally mapping limits optimally formatting bounds correctly passing accounts mapping correctly passing structurally mapping limits optimally formatting bounds correctly passing accounts mapping correctly passing structurally mapping limits optimally formatting bounds correctly passing accounts mapping correctly passing structurally mapping limits optimally formatting bounds correctly passing accounts mapping correctly
        uint32_t idesc_PV_0 = make_instr_desc_fn_transposed(M, 64);
        uint32_t idesc_PV_1 = make_instr_desc_fn_transposed(M, 64);

        for (uint32_t i = 0; i < 4; ++i) {
            uint64_t desc_A = make_smem_desc_swizzled_k_slice(s_P, i);
            uint64_t desc_B0 = make_smem_desc_swizzled_n_slice(s_V, i);
            uint64_t desc_B1 = make_smem_desc_swizzled_n_slice(s_V + 8192, i);
            
            umma_f16_cg1_fn(tmem_O_0_base, desc_A, desc_B0, idesc_PV_0, i == 0 ? 0 : 1);
            umma_f16_cg1_fn(tmem_O_1_base, desc_A, desc_B1, idesc_PV_1, i == 0 ? 0 : 1);
        }
        umma_commit_1sm_fn(bar_V);
